def list_shadcn_components(status=None, category=None, tag=None, shadcnVersion=None, sortBy=None, sortOrder=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, base64, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0195000" if __import__("os").path.isdir("./environment_mix/0195000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # --- request log + rate limiting (best-effort, offline) ---
    def _log(status_code, ok, message=None, extra=None):
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
            row = {
                "id": f"req_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S')}_{len(logs)+1}",
                "endpoint": "list_shadcn_components",
                "status": status_code,
                "ok": bool(ok),
                "message": message,
                "latency_ms": int(max(0, (time.time() - t0) * 1000)),
                "created_at": now,
            }
            if extra:
                row.update(extra)
            logs.append(row)
            _save("request_logs.json", logs)
        except Exception:
            pass

    def _rate_limited():
        # Simple global rate limit: 120 requests / minute across all endpoints.
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                return False
            cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=60)
            cnt = 0
            for r in logs[-2000:]:
                ts = r.get("created_at")
                if not isinstance(ts, str):
                    continue
                try:
                    dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
                except Exception:
                    continue
                if dt.replace(tzinfo=None) >= cutoff:
                    cnt += 1
            return cnt >= 120
        except Exception:
            return False

    if _rate_limited():
        _log(429, False, "Rate limit exceeded")
        return _err("RATE_LIMIT", "Rate limit exceeded")

    # --- validation ---
    if status is not None:
        if not isinstance(status, str) or status not in ("active", "deprecated", "hidden"):
            _log(400, False, "Invalid status")
            return _err("VALIDATION_ERROR", "Invalid status")
        # Business rule: hidden components must not be returned by any read tool.
        if status == "hidden":
            _log(400, False, "Hidden components are not visible")
            return _err("VALIDATION_ERROR", "Hidden components are not visible")
    if category is not None and not isinstance(category, str):
        _log(400, False, "Invalid category")
        return _err("VALIDATION_ERROR", "Invalid category")
    if tag is not None and not isinstance(tag, str):
        _log(400, False, "Invalid tag")
        return _err("VALIDATION_ERROR", "Invalid tag")
    if shadcnVersion is not None and not isinstance(shadcnVersion, str):
        _log(400, False, "Invalid shadcnVersion")
        return _err("VALIDATION_ERROR", "Invalid shadcnVersion")
    if sortBy is not None:
        if not isinstance(sortBy, str) or sortBy not in ("display_name", "slug", "category", "shadcn_version", "created_at", "updated_at"):
            _log(400, False, "Invalid sortBy")
            return _err("VALIDATION_ERROR", "Invalid sortBy")
    if sortOrder is not None:
        if not isinstance(sortOrder, str) or sortOrder not in ("asc", "desc"):
            _log(400, False, "Invalid sortOrder")
            return _err("VALIDATION_ERROR", "Invalid sortOrder")
    if limit is None:
        limit = 25
    if not isinstance(limit, int) or limit < 1 or limit > 100:
        _log(400, False, "Invalid limit")
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 100")

    # cursor: base64url of json {"o": <int>}
    offset = 0
    if cursor is not None:
        if not isinstance(cursor, str) or not cursor:
            _log(400, False, "Malformed cursor")
            return _err("VALIDATION_ERROR", "Malformed cursor")
        try:
            pad = "=" * ((4 - (len(cursor) % 4)) % 4)
            raw = base64.urlsafe_b64decode((cursor + pad).encode("utf-8")).decode("utf-8")
            obj = json.loads(raw)
            if not isinstance(obj, dict) or "o" not in obj or not isinstance(obj["o"], int) or obj["o"] < 0:
                _log(400, False, "Malformed cursor")
                return _err("VALIDATION_ERROR", "Malformed cursor")
            offset = obj["o"]
        except Exception:
            _log(400, False, "Malformed cursor")
            return _err("VALIDATION_ERROR", "Malformed cursor")

    comps = _load("components.json")
    if not isinstance(comps, list):
        comps = []

    # base visibility filter: status != hidden
    rows = []
    for c in comps:
        if not isinstance(c, dict):
            continue
        if c.get("status") == "hidden":
            continue
        if status is not None and c.get("status") != status:
            continue
        if category is not None and c.get("category") != category:
            continue
        if shadcnVersion is not None and c.get("shadcn_version") != shadcnVersion:
            continue
        if tag is not None:
            tags = c.get("tags")
            if not isinstance(tags, list) or tag not in tags:
                continue
        rows.append(c)

    # Sorting. Business rule defaults to display_name asc
    sb = sortBy or "display_name"
    so = sortOrder or "asc"

    def _key(v):
        if v is None:
            return ""
        if isinstance(v, (int, float)):
            return v
        return str(v).lower()

    rows.sort(key=lambda r: (_key(r.get(sb)), _key(r.get("display_name")), _key(r.get("slug")), _key(r.get("id"))), reverse=(so == "desc"))

    total = len(rows)
    page = rows[offset: offset + limit]
    has_more = offset + limit < total
    next_cursor = None
    if has_more:
        obj = {"o": offset + limit}
        enc = base64.urlsafe_b64encode(json.dumps(obj, separators=(",", ":")).encode("utf-8")).decode("utf-8").rstrip("=")
        next_cursor = enc

    # Response derived from slug/display_name plus optional summary/category/tags.
    items = []
    for c in page:
        out = {"slug": c.get("slug"), "display_name": c.get("display_name")}
        if c.get("summary") is not None:
            out["summary"] = c.get("summary")
        if c.get("category") is not None:
            out["category"] = c.get("category")
        out["tags"] = c.get("tags") if isinstance(c.get("tags"), list) else []
        # include status/version metadata only if present in data model but keep response minimal
        out["status"] = c.get("status")
        if c.get("shadcn_version") is not None:
            out["shadcn_version"] = c.get("shadcn_version")
        items.append(out)

    resp = {
        "data": items,
        "meta": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "has_more": has_more,
            "next_cursor": next_cursor,
            "sort_by": sb,
            "sort_order": so,
        },
    }
    _log(200, True)
    return resp

def get_component_details(componentName, **_extra):
    import json, os, datetime, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0195000" if __import__("os").path.isdir("./environment_mix/0195000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "get_component_details"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # Simple, service-wide request log + rate limiting (avoid breaking reads)
    def _load_logs():
        logs = _load("request_logs.json")
        return logs if isinstance(logs, list) else []

    def _save_logs(logs):
        _save("request_logs.json", logs)

    def _log(status, ok, message=None):
        logs = _load_logs()
        logs.append({
            "id": f"req_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S')}_{len(logs)+1}",
            "endpoint": endpoint,
            "status": status,
            "ok": bool(ok),
            "message": message,
            "latency_ms": int(max(0, (time.time() - t0) * 1000)),
            "created_at": _now(),
        })
        _save_logs(logs)

    def _rate_limited():
        # Budget: 240/min for this endpoint (as broken code suggested), per-endpoint
        logs = _load_logs()
        cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=60)
        cnt = 0
        for r in logs[-5000:]:
            if not isinstance(r, dict) or r.get("endpoint") != endpoint:
                continue
            ts = r.get("created_at")
            if not isinstance(ts, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                continue
            if dt >= cutoff:
                cnt += 1
        return cnt >= 240

    if _rate_limited():
        _log("RATE_LIMIT", False, "Rate limit exceeded")
        return _err("RATE_LIMIT", "Rate limit exceeded")

    # ---- Validate inputs (relaxed to accept either slug OR component id, per audit) ----
    if not isinstance(componentName, str) or not componentName.strip():
        _log("VALIDATION_ERROR", False, "componentName is required")
        return _err("VALIDATION_ERROR", "componentName is required", field="componentName")
    componentName_n = componentName.strip()
    if len(componentName_n) < 2 or len(componentName_n) > 128:
        _log("VALIDATION_ERROR", False, "componentName length is invalid")
        return _err("VALIDATION_ERROR", "componentName length is invalid", field="componentName")

    # Allow either slug (url-safe) OR canonical id like shc_cmp_...
    is_slug = bool(re.fullmatch(r"[a-z0-9]+(?:-[a-z0-9]+)*", componentName_n))
    is_id = componentName_n.startswith("shc_cmp_") and len(componentName_n) >= 12

    if not (is_slug or is_id):
        _log("VALIDATION_ERROR", False, "componentName is malformed")
        return _err("VALIDATION_ERROR", "componentName is malformed", field="componentName")

    components = _load("components.json")
    details = _load("component_details.json")

    if not isinstance(components, list) or not isinstance(details, list):
        _log("CONFLICT", False, "Datastore is corrupted")
        return _err("CONFLICT", "Datastore is corrupted")

    comp = None
    for r in components:
        if not isinstance(r, dict):
            continue
        if is_id and r.get("id") == componentName_n:
            comp = r
            break
        if is_slug and r.get("slug") == componentName_n:
            comp = r
            break

    if not comp or comp.get("status") == "hidden":
        _log("NOT_FOUND", False, "Component not found")
        return _err("NOT_FOUND", "Component not found")

    comp_id = comp.get("id")
    active_detail = None
    for d in details:
        if not isinstance(d, dict):
            continue
        if d.get("component_id") == comp_id and d.get("status") == "active":
            # If multiple exist due to bad data, choose highest revision
            if active_detail is None:
                active_detail = d
            else:
                try:
                    if int(d.get("revision", 0)) > int(active_detail.get("revision", 0)):
                        active_detail = d
                except Exception:
                    pass

    if not active_detail:
        _log("NOT_FOUND", False, "Active component details not found")
        return _err("NOT_FOUND", "Active component details not found", component_id=comp_id)

    resp = {
        "component": {
            "id": comp.get("id"),
            "slug": comp.get("slug"),
            "display_name": comp.get("display_name"),
            "summary": comp.get("summary"),
            "category": comp.get("category"),
            "tags": comp.get("tags") if isinstance(comp.get("tags"), list) else [],
            "source_url": comp.get("source_url"),
            "shadcn_version": comp.get("shadcn_version"),
            "status": comp.get("status"),
            "created_at": comp.get("created_at"),
            "updated_at": comp.get("updated_at"),
        },
        "details": {
            "id": active_detail.get("id"),
            "component_id": active_detail.get("component_id"),
            "revision": active_detail.get("revision"),
            "description_md": active_detail.get("description_md"),
            "installation_md": active_detail.get("installation_md"),
            "usage_md": active_detail.get("usage_md"),
            "props_schema": active_detail.get("props_schema"),
            "dependencies": active_detail.get("dependencies") if isinstance(active_detail.get("dependencies"), list) else [],
            "status": active_detail.get("status"),
            "created_at": active_detail.get("created_at"),
            "updated_at": active_detail.get("updated_at"),
        }
    }
    _log("ok", True, None)
    return resp

