def search_components(query, **_extra):
    import json, os, datetime, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0195000" if __import__("os").path.isdir("./environment_mix/0195000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    # --- rate limit specific to search volume ---
    def _rate_limited():
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                return False
            cutoff = now_dt - datetime.timedelta(seconds=60)
            cnt = 0
            for r in logs[-5000:]:
                if r.get("endpoint") != "search_components":
                    continue
                ts = r.get("created_at")
                if not isinstance(ts, str):
                    continue
                try:
                    dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
                except Exception:
                    continue
                if dt.replace(tzinfo=None) >= cutoff:
                    cnt += 1
            return cnt >= 30
        except Exception:
            return False

    def _log(status_code, ok, message=None, extra=None):
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
            row = {
                "id": f"req_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S')}_{len(logs)+1}",
                "endpoint": "search_components",
                "status": status_code,
                "ok": bool(ok),
                "message": message,
                "latency_ms": int(max(0, (time.time() - t0) * 1000)),
                "created_at": now,
            }
            if extra:
                row.update(extra)
            logs.append(row)
            _save("request_logs.json", logs)
        except Exception:
            pass

    if _rate_limited():
        _log(429, False, "Rate limit exceeded")
        return _err("RATE_LIMIT", "Rate limit exceeded")

    if not isinstance(query, str):
        _log(400, False, "query must be a string")
        return _err("VALIDATION_ERROR", "query must be a string")
    query_text = query
    q = query.strip()
    if len(q) < 1 or len(q) > 256:
        _log(400, False, "query length must be between 1 and 256")
        return _err("VALIDATION_ERROR", "query length must be between 1 and 256")
    normalized = q.lower()

    comps = _load("components.json")
    if not isinstance(comps, list):
        comps = []

    # Match strategies:
    # - tag: exact match against tags
    # - like: substring match against search_text/display_name/slug
    # Prefer tag if exact tag hit exists; else like (stand-in for fts).
    tag_hits = []
    like_hits = []

    for c in comps:
        if not isinstance(c, dict):
            continue
        if c.get("status") == "hidden":
            continue

        slug = c.get("slug") or ""
        dn = c.get("display_name") or ""
        st = c.get("search_text") or ""
        tags = c.get("tags") if isinstance(c.get("tags"), list) else []

        # tag match (case-insensitive exact)
        if any(isinstance(t, str) and t.lower() == normalized for t in tags):
            tag_hits.append(c)
            continue

        hay = " ".join([str(slug), str(dn), str(st)]).lower()
        if normalized in hay:
            # crude relevance: occurrences + prefix boost
            occ = hay.count(normalized)
            prefix = 1 if str(slug).lower().startswith(normalized) else 0
            like_hits.append((-(occ * 10 + prefix * 5), str(dn).lower(), str(slug).lower(), c))

    match_strategy = "tag" if tag_hits else "like"
    if match_strategy == "tag":
        # stable ordering by display_name
        tag_hits.sort(key=lambda c: (str(c.get("display_name") or "").lower(), str(c.get("slug") or "").lower(), str(c.get("id") or "")))
        matched = tag_hits
    else:
        like_hits.sort(key=lambda x: (x[0], x[1], x[2], str(x[3].get("id") or "")))
        matched = [x[3] for x in like_hits]

    # Return top N for search (implicit)
    matched = matched[:50]

    matched_ids = [m.get("id") for m in matched if isinstance(m, dict) and isinstance(m.get("id"), str)]
    result_count = len(matched_ids)

    # Write immutable search_queries log row
    try:
        sq = _load("search_queries.json")
        if not isinstance(sq, list):
            sq = []
        new_id = f"sq_{now_dt.strftime('%Y%m%d%H%M%S')}_{len(sq)+1}"
        sq_row = {
            "id": new_id,
            "query_text": query_text,
            "normalized_query": normalized,
            "matched_component_ids": matched_ids,
            "result_count": result_count,
            "match_strategy": match_strategy,
            "request_source": None,
            "created_at": now,
            "updated_at": now,  # must equal created_at
        }
        # enforce constraints defensively
        if not (1 <= len(query_text) <= 256):
            raise ValueError("invalid query_text length")
        if sq_row["result_count"] != len(sq_row["matched_component_ids"]):
            sq_row["result_count"] = len(sq_row["matched_component_ids"])
        sq.append(sq_row)
        _save("search_queries.json", sq)
    except Exception:
        # If logging fails, still return the search results (service should not crash).
        pass

    out = []
    for c in matched:
        out.append({
            "slug": c.get("slug"),
            "display_name": c.get("display_name"),
            "summary": c.get("summary"),
            "category": c.get("category"),
            "tags": c.get("tags") if isinstance(c.get("tags"), list) else [],
            "status": c.get("status"),
            "shadcn_version": c.get("shadcn_version"),
        })

    resp = {
        "data": out,
        "meta": {
            "query": query_text,
            "normalized_query": normalized,
            "match_strategy": match_strategy,
            "count": len(out),
        },
    }
    _log(200, True, extra={"search_count": len(out)})
    return resp

