            if not isinstance(ts, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                continue
            if dt >= cutoff:
                cnt += 1
        return cnt >= 30

    if _rate_limited():
        _log("RATE_LIMIT", False, "Rate limit exceeded")
        return _err("RATE_LIMIT", "Rate limit exceeded")

    # ---- Validate inputs ----
    if not isinstance(componentName, str) or not componentName.strip():
        _log("VALIDATION_ERROR", False, "componentName is required")
        return _err("VALIDATION_ERROR", "componentName is required", field="componentName")
    componentName_n = componentName.strip()
    is_slug = bool(re.fullmatch(r"[a-z0-9]+(?:-[a-z0-9]+)*", componentName_n))
    is_id = componentName_n.startswith("shc_cmp_") and len(componentName_n) >= 12
    if not (is_slug or is_id):
        _log("VALIDATION_ERROR", False, "componentName is malformed")
        return _err("VALIDATION_ERROR", "componentName is malformed", field="componentName")

    if not isinstance(revision, int) or revision < 1:
        _log("VALIDATION_ERROR", False, "revision must be >= 1")
        return _err("VALIDATION_ERROR", "revision must be an integer >= 1", field="revision")

    if not isinstance(description_md, str) or not description_md.strip():
        _log("VALIDATION_ERROR", False, "description_md is required")
        return _err("VALIDATION_ERROR", "description_md must be a non-empty string", field="description_md")

    if installation_md is not None and not isinstance(installation_md, str):
        _log("VALIDATION_ERROR", False, "installation_md must be a string or null")
        return _err("VALIDATION_ERROR", "installation_md must be a string or null", field="installation_md")
    if usage_md is not None and not isinstance(usage_md, str):
        _log("VALIDATION_ERROR", False, "usage_md must be a string or null")
        return _err("VALIDATION_ERROR", "usage_md must be a string or null", field="usage_md")
    if props_schema is not None and not isinstance(props_schema, dict):
        _log("VALIDATION_ERROR", False, "props_schema must be an object or null")
        return _err("VALIDATION_ERROR", "props_schema must be an object or null", field="props_schema")
    if dependencies is None:
        dependencies_n = []
    else:
        if not isinstance(dependencies, list) or any(not isinstance(d, str) for d in dependencies):
            _log("VALIDATION_ERROR", False, "dependencies must be an array of strings")
            return _err("VALIDATION_ERROR", "dependencies must be an array of strings", field="dependencies")
        dependencies_n = [d.strip() for d in dependencies]

    if status is None:
        status_n = "draft"
    else:
        if not isinstance(status, str) or status not in ("draft", "active", "superseded"):
            _log("VALIDATION_ERROR", False, "status is invalid")
            return _err("VALIDATION_ERROR", "status must be one of: draft, active, superseded", field="status")
        status_n = status

    # ---- Load store ----
    components = _load("components.json")
    details = _load("component_details.json")
    examples = _load("component_examples.json")
    if not isinstance(components, list) or not isinstance(details, list) or not isinstance(examples, list):
        _log("CONFLICT", False, "Datastore is corrupted")
        return _err("CONFLICT", "Datastore is corrupted")

    # ---- Resolve component, enforce visibility (cannot create details for hidden component) ----
    comp = None
    for c in components:
        if not isinstance(c, dict):
            continue
        if is_id and c.get("id") == componentName_n:
            comp = c
            break
        if is_slug and c.get("slug") == componentName_n:
            comp = c
            break
    if not comp or comp.get("status") == "hidden":
        _log("NOT_FOUND", False, "Component not found")
        return _err("NOT_FOUND", "Component not found")

    comp_id = comp.get("id")

    # unique(component_id, revision)
    for d in details:
        if isinstance(d, dict) and d.get("component_id") == comp_id and d.get("revision") == revision:
            _log("CONFLICT", False, "A details revision with this (component_id, revision) already exists")
            return _err("CONFLICT", "A details revision with this revision already exists for the component.", field="revision")

    now = _now()
    suffix = datetime.datetime.utcnow().strftime("%y%m%d%H%M%S") + "".join(random.choice(string.ascii_uppercase + string.digits) for _ in range(10))
    new_id = "shc_det_" + suffix

    new_row = {
        "id": new_id,
        "component_id": comp_id,
        "revision": revision,
        "description_md": description_md,
        "installation_md": installation_md,
        "usage_md": usage_md,
        "props_schema": props_schema,
        "dependencies": dependencies_n,
        "status": status_n,
        "created_at": now,
        "updated_at": now,
    }

    # If status is active, enforce "only one active": supersede previous active atomically
    if status_n == "active":
        for d in details:
            if isinstance(d, dict) and d.get("component_id") == comp_id and d.get("status") == "active":
                d["status"] = "superseded"
                d["updated_at"] = now

    details.append(new_row)

    # Recompute component.search_text (rule: description_md/props_schema changes trigger recompute)
    parts = []
    for key in ("slug", "display_name", "summary", "category", "shadcn_version"):
        v = comp.get(key)
        if isinstance(v, str) and v.strip():
            parts.append(v.strip())
    if isinstance(comp.get("tags"), list):
        for t in comp.get("tags"):
            if isinstance(t, str) and t.strip():
                parts.append(t.strip())

    # include active details after insertion
    active_details = []
    for d in details:
        if isinstance(d, dict) and d.get("component_id") == comp_id and d.get("status") == "active":
            active_details.append(d)
    if active_details:
        best = active_details[0]
        for d in active_details[1:]:
            try:
                if int(d.get("revision", 0)) > int(best.get("revision", 0)):
                    best = d
            except Exception:
                pass
        if isinstance(best.get("description_md"), str) and best.get("description_md").strip():
            parts.append(best.get("description_md"))
        ps = best.get("props_schema")
        if isinstance(ps, dict):
            try:
                parts.append(json.dumps(ps, ensure_ascii=False, sort_keys=True))
            except Exception:
                pass
        if isinstance(best.get("installation_md"), str) and best.get("installation_md").strip():
            parts.append(best.get("installation_md"))
        if isinstance(best.get("usage_md"), str) and best.get("usage_md").strip():
            parts.append(best.get("usage_md"))
        if isinstance(best.get("dependencies"), list):
            for dep in best.get("dependencies"):
                if isinstance(dep, str) and dep.strip():
                    parts.append(dep.strip())

    # include active examples
    for ex in examples:
        if not isinstance(ex, dict):
            continue
        if ex.get("component_id") != comp_id or ex.get("status") != "active":
            continue
        for k in ("title", "description", "code", "language"):
            v = ex.get(k)
            if isinstance(v, str) and v.strip():
                parts.append(v.strip())

    comp_updated = False
    for i, c in enumerate(components):
        if isinstance(c, dict) and c.get("id") == comp_id:
            c["search_text"] = "\n".join(parts)
            c["updated_at"] = now
            components[i] = c
            comp_updated = True
            break
    if not comp_updated:
        _log("NOT_FOUND", False, "Component disappeared during update")
        return _err("NOT_FOUND", "Component not found")

    # Persist (best-effort atomicity via ordering; no blanket except)
    try:
        _save("component_details.json", details)
        _save("components.json", components)
    except Exception:
        _log("CONFLICT", False, "Failed to persist component details")
        return _err("CONFLICT", "Failed to persist component details")

    _log("ok", True, None)
    return {"details": new_row}

def update_component_details_status(id, status, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0195000" if __import__("os").path.isdir("./environment_mix/0195000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "update_component_details_status"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _load_logs():
        logs = _load("request_logs.json")
        return logs if isinstance(logs, list) else []

    def _append_log(status_code, ok, message=None):
        logs = _load_logs()
        logs.append({
            "id": f"req_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S')}_{len(logs)+1}",
            "endpoint": endpoint,
            "status": status_code,
            "ok": bool(ok),
            "message": message,
            "latency_ms": int(max(0, (time.time() - t0) * 1000)),
            "created_at": _now(),
        })
        _save("request_logs.json", logs)

    def _rate_limited():
        logs = _load_logs()
        cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=60)
        cnt = 0
        for r in logs[-5000:]:
            if not isinstance(r, dict) or r.get("endpoint") != endpoint:
                continue
            ts = r.get("created_at")
            if not isinstance(ts, str):
                continue
            try:
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                continue
            if dt >= cutoff:
                cnt += 1
        return cnt >= 60

    if _rate_limited():
        _append_log("RATE_LIMIT", False, "Rate limit exceeded")
        return _err("RATE_LIMIT", "Rate limit exceeded")

    # Validate inputs
    if not isinstance(id, str) or not id.strip():
        _append_log("VALIDATION_ERROR", False, "id must be a non-empty string")
        return _err("VALIDATION_ERROR", "id must be a non-empty string", field="id")
    if not isinstance(status, str) or status not in ("draft", "active", "superseded"):
        _append_log("VALIDATION_ERROR", False, "status must be one of: draft, active, superseded")
        return _err("VALIDATION_ERROR", "status must be one of: draft, active, superseded", field="status")

    target_id = id.strip()

    details = _load("component_details.json")
    if not isinstance(details, list):
        details = []

    target = None
    for r in details:
        if isinstance(r, dict) and r.get("id") == target_id:
            target = r
            break

    # Audit defect: callers sometimes pass a component_id (shc_cmp_...) instead of details id.
    # To behave robustly like a real backend, if no row matches by details.id and the id looks like a component id,
    # resolve the latest revision for that component and apply the transition there.
    resolved_by_component = False
    if target is None and target_id.startswith("shc_cmp_"):
        candidates = [r for r in details if isinstance(r, dict) and r.get("component_id") == target_id]
        if candidates:
            def _rev_key(x):
                rv = x.get("revision")
                return rv if isinstance(rv, int) else -1
            candidates.sort(key=_rev_key, reverse=True)
            target = candidates[0]
            resolved_by_component = True

    if target is None:
        _append_log("NOT_FOUND", False, "component_details revision not found")
        return _err("NOT_FOUND", "component_details revision not found", id=target_id)

    current = target.get("status")
    if current not in ("draft", "active", "superseded"):
        _append_log("CONFLICT", False, "component_details has invalid current status")
        return _err("CONFLICT", "component_details has invalid current status", id=target.get("id"), current_status=current)

    transitions = {
        "draft": ("active",),
        "active": ("superseded",),
        "superseded": tuple(),
    }
    if status == current:
        # Idempotent transition
        _append_log("OK", True, "no-op (already in target status)")
        return {"component_details": target, "resolved_by_component_id": resolved_by_component}

    if status not in transitions.get(current, ()):
        _append_log("INVALID_TRANSITION", False, f"illegal transition {current}→{status}")
        return _err(
            "INVALID_TRANSITION",
            f"Illegal status transition for component_details: {current}→{status}. Allowed: {list(transitions.get(current, ())) }",
            id=target.get("id"),
            from_status=current,
            to_status=status
        )

    now = _now()

    # If promoting to active, atomically supersede any currently-active revision for the same component_id
    if status == "active":
        comp_id = target.get("component_id")
        if not isinstance(comp_id, str) or not comp_id:
            _append_log("CONFLICT", False, "component_id missing on details row")
            return _err("CONFLICT", "component_id missing on details row", id=target.get("id"))

        # Mark any other active details for this component as superseded
        for r in details:
            if not isinstance(r, dict):
                continue
            if r.get("component_id") != comp_id:
                continue
            if r.get("status") == "active" and r.get("id") != target.get("id"):
                r["status"] = "superseded"
                r["updated_at"] = now

        # Promote target
        target["status"] = "active"
        target["updated_at"] = now

    elif status == "superseded":
        target["status"] = "superseded"
        target["updated_at"] = now

    _save("component_details.json", details)
    _append_log("OK", True, "updated")
    return {"component_details": target, "resolved_by_component_id": resolved_by_component}
